fn to_u32(count: usize) -> u32 {
    u32::try_from(count).unwrap_or(u32::MAX)
}

fn named(name: String, args: Vec<PropType>) -> PropType {
    PropType::Named { name: name.into(), args }
}

/// The types whose conversion needs nothing but their flags.
fn simple(info: &TypeInfo) -> Option<PropType> {
    let flags = info.flags;
    // `boolean` is the union `false | true` and carries both flags.
    if flags & flag::BOOLEAN != 0 {
        return Some(PropType::Boolean);
    }
    let known = [
        (flag::ANY, PropType::Any),
        (flag::UNKNOWN, PropType::Unknown),
        (flag::UNDEFINED, PropType::Undefined),
        (flag::NULL, PropType::Null),
        (flag::VOID, PropType::Void),
        (flag::NEVER, PropType::Never),
        (flag::STRING, PropType::String),
        (flag::NUMBER, PropType::Number),
        (flag::BIG_INT, PropType::BigInt),
        (flag::ES_SYMBOL, named("symbol".to_string(), Vec::new())),
        (flag::NON_PRIMITIVE, named("object".to_string(), Vec::new())),
    ];
    known.into_iter().find(|(bit, _)| flags & bit != 0).map(|(_, converted)| converted)
}

/// A union of converted members: `false | true` is `boolean`, a union inside a union is flattened, a repeated member
/// is kept once, and a union of one is that member.
fn union_of(converted: Vec<PropType>) -> PropType {
    let mut flat = Vec::with_capacity(converted.len());
    for member in converted {
        match member {
            PropType::Union(inner) => flat.extend(inner),
            other => flat.push(other),
        }
    // TypeScript built-in utility types, DOM element types, and React HTML
    // attribute types all appear as prop types in real-world .d.ts files but
    // cannot be expanded without a type-checker. Return Named silently.
    let bare = name.strip_prefix("React.").unwrap_or(name.as_str());
    // A lib alias that evaluates (`Exclude`, `Extract`, `NonNullable`) is read from TypeScript's own definition.
    if !args.is_empty()
        && let Some(evaluated) = evaluate_lib_alias(bare, args, consuming_file, ctx, state, depth)
    {
        return evaluated;
    }
    if super::is_ts_utility_type(bare)
        || matches!(
            bare,
            // TypeScript primitives used as type names
            "object" | "Object" | "Function" | "Symbol" | "BigInt"
            // React HTML attribute types (not in is_react_builtin; appear as prop types)
            | "HTMLAttributes" | "InputHTMLAttributes" | "TextareaHTMLAttributes"
            | "SelectHTMLAttributes" | "ButtonHTMLAttributes" | "AnchorHTMLAttributes"
            | "FormHTMLAttributes" | "LabelHTMLAttributes" | "ImgHTMLAttributes"
            | "VideoHTMLAttributes" | "AudioHTMLAttributes" | "DOMAttributes"
            | "AriaAttributes" | "HTMLInputTypeAttribute" | "HTMLAttributeReferrerPolicy"
            | "HTMLAttributeAnchorTarget" | "HTMLInputAutoCompleteAttribute"
            // React SVG/generic HTML prop types
            | "SVGAttributes" | "SVGProps" | "HTMLProps"
            // React component utility types
            | "ComponentRef" | "JSXElementConstructor"
